			charge_id BIGINT NOT NULL,
			note       TEXT   NOT NULL);
		CREATE TABLE IF NOT EXISTS receipts (
			id         BIGSERIAL PRIMARY KEY,
			charge_id BIGINT NOT NULL)`)
	return err
}

func (s *Store) Get(ctx context.Context, id int64) (Charge, error) {
	return s.one(ctx, `SELECT id, amount, currency, status FROM charges
		WHERE id = $1`, id)
}

func (s *Store) Latest(ctx context.Context) (Charge, error) {
	return s.one(ctx, `SELECT id, amount, currency, status FROM charges
		ORDER BY id DESC LIMIT 1`)
}

// listLimit caps how many charges one page returns.
const listLimit = 50

// List returns charges by id ascending. An empty currency means no filter.
func (s *Store) List(ctx context.Context, currency string) ([]Charge, error) {
